mkdir -p /tmp/bot-check && cat > /tmp/bot-check/test.mjs <<'EOF'
import assert from 'node:assert/strict';
import { onInbound, check } from '<HOME>/Desktop/Open-Source/projelerim/proactive-gate/bench/head-to-head/results/round6-heldout-c-haiku/work/baseline-g5-1/bot.mjs';

const H = 3600_000;
const T0 = new Date('2026-10-23T10:00:00Z');
const at = (h) => new Date(T0.getTime() + h * H);
let n = 0;
const id = () => `u${++n}`;

// never wrote: nothing allowed
{ const u = id(); assert.deepEqual(check(u, 'freeform', at(0)), { allowed: false, rule: 'no_prior_inbound' });
  assert.deepEqual(check(u, 'template', at(0)), { allowed: false, rule: 'no_prior_inbound' }); }

// freeform window: open just before 24h, closed at 24h
{ const u = id(); onInbound(u, 'hi', at(0));
  assert.deepEqual(check(u, 'freeform', at(1)), { allowed: true, rule: null });
  assert.deepEqual(check(u, 'freeform', at(23.99)), { allowed: true, rule: null });
  assert.deepEqual(check(u, 'freeform', at(24)), { allowed: false, rule: 'outside_24h_window' });
  assert.deepEqual(check(u, 'template', at(100)), { allowed: true, rule: null }); }

// later inbound extends window
{ const u = id(); onInbound(u, 'hi', at(0)); onInbound(u, 'again', at(30));
  assert.deepEqual(check(u, 'freeform', at(50)), { allowed: true, rule: null }); }

// out-of-order inbound does not shrink window
{ const u = id(); onInbound(u, 'hi', at(10)); onInbound(u, 'old', at(0));
  assert.deepEqual(check(u, 'freeform', at(30)), { allowed: true, rule: null }); }

// now before last inbound / invalid now: fail closed
{ const u = id(); onInbound(u, 'hi', at(5));
  assert.deepEqual(check(u, 'freeform', at(4)), { allowed: false, rule: 'invalid_now' });
  assert.deepEqual(check(u, 'freeform', new Date('x')), { allowed: false, rule: 'invalid_now' }); }

// unknown type
{ const u = id(); onInbound(u, 'hi', at(0));
  assert.deepEqual(check(u, 'carrier-pigeon', at(1)), { allowed: false, rule: 'unknown_message_type' }); }

// STOP variants block everything; case/punctuation/spacing tolerant
const stopVariants = ['STOP', ' stop ', 'Stop.', 'stop!!!', '  S T O P? ', 'stop\n', 'Stop​', 'ｓｔｏｐ',
  'STOPALL', 'stop all', 'Stop-All', 'unsubscribe', 'UNSUBSCRIBE!', 'cancel', 'END', 'quit', 'Opt-Out', 'optout', ' stop '];
for (const s of stopVariants) {
  const u = id();
  onInbound(u, 'hello', at(0));
  onInbound(u, s, at(1));
  assert.deepEqual(check(u, 'template', at(2)), { allowed: false, rule: 'opted_out' }, JSON.stringify(s));
  assert.deepEqual(check(u, 'freeform', at(2)), { allowed: false, rule: 'opted_out' }, JSON.stringify(s));
}

// STOP for a user who never wrote before still blocks (and STOP is inbound)
{ const u = id(); onInbound(u, 'STOP', at(0));
  assert.deepEqual(check(u, 'template', at(1)), { allowed: false, rule: 'opted_out' }); }

// STOP works even when `at` is malformed
{ const u = id(); onInbound(u, 'hi', at(0)); onInbound(u, 'STOP', undefined);
  assert.deepEqual(check(u, 'template', at(1)), { allowed: false, rule: 'opted_out' }); }

// ordinary sentences containing keywords are NOT opt-outs
const normal = ['I cannot stop thinking about my bill', 'stop texting me', 'please stop', 'can you end my contract',
  'Can you start my service tomorrow?', 'do not cancel my plan', 'the end', 'stopping by the shop', 'stop it', 'yes', 'no stop'];
for (const s of normal) {
  const u = id();
  onInbound(u, s, at(0));
  assert.deepEqual(check(u, 'freeform', at(1)), { allowed: true, rule: null }, s);
}

// START / UNSTOP re-enable; YES does not
{ const u = id(); onInbound(u, 'hi', at(0)); onInbound(u, 'STOP', at(1));
  onInbound(u, 'yes', at(2));
  assert.deepEqual(check(u, 'template', at(3)), { allowed: false, rule: 'opted_out' });
  onInbound(u, ' Start! ', at(4));
  assert.deepEqual(check(u, 'template', at(5)), { allowed: true, rule: null });
  assert.deepEqual(check(u, 'freeform', at(5)), { allowed: true, rule: null });
  onInbound(u, 'stop', at(6));
  onInbound(u, 'unstop', at(7));
  assert.deepEqual(check(u, 'template', at(8)), { allowed: true, rule: null }); }

// opt-out is per user
{ const a = id(), b = id(); onInbound(a, 'hi', at(0)); onInbound(b, 'hi', at(0)); onInbound(a, 'STOP', at(1));
  assert.deepEqual(check(b, 'freeform', at(2)), { allowed: true, rule: null }); }

// non-string text is treated as no keyword
{ const u = id(); onInbound(u, null, at(0)); onInbound(u, undefined, at(0));
  assert.deepEqual(check(u, 'template', at(1)), { allowed: true, rule: null }); }

console.log('all checks passed');
EOF
